### collect_sequencing_metrics.R ###################################################################
# Finds and combines output generated by picard/gatk4

### FUNCTIONS ######################################################################################
# function to generate a standardized filename
generate.filename <- function(project.stem, file.core, extension, include.date = TRUE) {

    # build up the filename
    file.name <- paste(project.stem, file.core, sep = '_');
    file.name <- paste(file.name, extension, sep = '.');

    if (include.date) {
        file.name <- paste(Sys.Date(), file.name, sep = '_');
    }

    return(file.name);
}

### PREPARE SESSION ################################################################################
# import libraries
library(argparse);

# import command line arguments
parser <- ArgumentParser();

parser$add_argument('-p', '--project', type = 'character', help = 'project name');
parser$add_argument('-d', '--directory', type = 'character', help = 'path to data directory');

arguments <- parser$parse_args();

setwd(arguments$directory);

### MAIN ###########################################################################################
# find results files from VG stats
vg.files <- list.files(pattern = 'vg_aligned_stats.txt', recursive = TRUE);

# find results files from GATK/Picard CollectAlignmentMetrics
gatk.files <- list.files(pattern = 'final_alignment_metrics.txt', recursive = TRUE);

# find results from GATK/Picard CalculateContamination
contamination.files <- list.files(pattern = 'contamination_estimate.tsv', recursive = TRUE);


# read in and format VG metrics
if (length(vg.files) > 0) {
	qc.data <- do.call(rbind, lapply(vg.files, function(i) {
		smp <- unlist(strsplit(basename(i),'_vg'))[1];
		tmp <- read.table(i, header = F, nrow = 8, sep = ':');
		df <- data.frame(
			Sample = smp,
			TOTAL_READS = tmp[grepl('alignments', tmp$V1),]$V2,
			ALIGNED_READS = tmp[grepl('aligned', tmp$V1),]$V2,
			READS_ALIGNED_IN_PAIRS = tmp[grepl('Total paired', tmp$V1),]$V2,
			PROPER_PAIRS = tmp[grepl('properly', tmp$V1),]$V2
		);
		return(df);
	}));

	qc.data$UNALIGNED_READS <- qc.data$TOTAL_READS - qc.data$ALIGNED_READS;
	qc.data$PCT_UNALIGNED_READS <- qc.data$UNALIGNED_READS / qc.data$TOTAL_READS;
	qc.data$PCT_PROPER_PAIRS <- qc.data$PROPER_PAIRS / qc.data$ALIGNED_READS;

	write.table(
		qc.data,
		file = generate.filename(arguments$project, 'vg_alignment_statistics', 'tsv'),
		row.names = FALSE,
		col.names = TRUE,
		sep = '\t'
	);
}

# read in and format GATK metrics
if (length(gatk.files) > 0) {
	qc.data <- do.call(rbind, lapply(gatk.files, function(i) {
		tmp <- read.delim(i, skip = 6, nrow = 3);
		tmp <- tmp[,c('SAMPLE','CATEGORY','TOTAL_READS','PF_READS_ALIGNED','MEAN_ALIGNED_READ_LENGTH',
			'AVG_POS_3PRIME_SOFTCLIP_LENGTH','READS_ALIGNED_IN_PAIRS','PF_READS_IMPROPER_PAIRS')];
		tmp$SAMPLE <- unlist(strsplit(basename(i),'_final'))[1];
		return(tmp);
	}));

	qc.data$UNALIGNED_READS <- qc.data$TOTAL_READS - qc.data$PF_READS_ALIGNED;
	qc.data$PCT_UNALIGNED_READS <- qc.data$UNALIGNED_READS / qc.data$TOTAL_READS;
	qc.data$PROPER_PAIRS <- qc.data$PF_READS_ALIGNED - qc.data$PF_READS_IMPROPER_PAIRS;
	qc.data$PCT_PROPER_PAIRS <- qc.data$PROPER_PAIRS / qc.data$PF_READS_ALIGNED;

	write.table(
		qc.data[which(qc.data$CATEGORY == 'PAIR'),],
		file = generate.filename(arguments$project, 'gatk_alignment_statistics','tsv'),
		row.names = FALSE,
		col.names = TRUE,
		sep = '\t'
	);
}

# read in and format contamination estimates
if (length(contamination.files) > 0) {

	contam.data <- do.call(rbind, lapply(contamination.files, read.delim))

	write.table(
		contam.data,
		file = generate.filename(arguments$project, 'contamination_estimates','tsv'),
		row.names = FALSE,
		col.names = TRUE,
		sep = '\t'
	);
}
